mapper.insert:
INSERT INTO MES_TQ_SCHEDULE_RESULT ( SCHEDULE_DATE, BATCH_NO, ORDER_NO, BEAD_CODE, MATERIAL_CODE, STEEL_RING_CODE, GLUE_CODE, MOUTH_PLATE_CODE, SPEC_SIZE, MACHINE_CODE, UNIT_CONSUME, STOCK_QTY, SUPPLY_TIME, NIGHT_PLAN_QTY, NIGHT_PRODUCE_ORDER, NIGHT_SYS_ANALYSIS, NIGHT_HAND_ANALYSIS, NIGHT_REMARK, DAY_PLAN_QTY, DAY_PRODUCE_ORDER, DAY_SYS_ANALYSIS, DAY_HAND_ANALYSIS, DAY_REMARK, MID_PLAN_QTY, MID_PRODUCE_ORDER, MID_SYS_ANALYSIS, MID_HAND_ANALYSIS, MID_REMARK, CX_CLASS3_PLAN, CX_CLASS4_PLAN, CX_CLASS5_PLAN, CX_CLASS6_PLAN, CX_CLASS7_PLAN, CX_CLASS8_PLAN, REMARK, DATA_VERSION, COMPANY_CODE, FACTORY_CODE ) SELECT * FROM (
SELECT #{item.scheduleDate,jdbcType=DATE} AS SCHEDULE_DATE, #{item.batchNo,jdbcType=VARCHAR} AS BATCH_NO, #{item.orderNo,jdbcType=VARCHAR} AS ORDER_NO, #{item.beadCode,jdbcType=VARCHAR} AS BEAD_CODE, #{item.materialCode,jdbcType=VARCHAR} AS MATERIAL_CODE, #{item.steelRingCode,jdbcType=VARCHAR} AS STEEL_RING_CODE, #{item.glueCode,jdbcType=VARCHAR} AS GLUE_CODE, #{item.mouthPlateCode,jdbcType=VARCHAR} AS MOUTH_PLATE_CODE, #{item.specSize,jdbcType=VARCHAR} AS SPEC_SIZE, #{item.machineCode,jdbcType=VARCHAR} AS MACHINE_CODE, #{item.unitConsume,jdbcType=DOUBLE} AS UNIT_CONSUME, #{item.stockQty,jdbcType=DOUBLE} AS STOCK_QTY, #{item.supplyTime,jdbcType=DOUBLE} AS SUPPLY_TIME, #{item.nightPlanQty,jdbcType=DOUBLE} AS NIGHT_PLAN_QTY, #{item.nightProduceOrder,jdbcType=INTEGER} AS NIGHT_PRODUCE_ORDER, #{item.nightSysAnalysis,jdbcType=VARCHAR} AS NIGHT_SYS_ANALYSIS, #{item.nightHandAnalysis,jdbcType=VARCHAR} AS NIGHT_HAND_ANALYSIS, #{item.nightSysAnalysis,jdbcType=VARCHAR} AS NIGHT_REMARK, #{item.dayPlanQty,jdbcType=DOUBLE} AS DAY_PLAN_QTY, #{item.dayProduceOrder,jdbcType=INTEGER} AS DAY_PRODUCE_ORDER, #{item.daySysAnalysis,jdbcType=VARCHAR} AS DAY_SYS_ANALYSIS, #{item.dayHandAnalysis,jdbcType=VARCHAR} AS DAY_HAND_ANALYSIS, #{item.daySysAnalysis,jdbcType=VARCHAR} AS DAY_REMARK, #{item.midPlanQty,jdbcType=DOUBLE} AS MID_PLAN_QTY, #{item.midProduceOrder,jdbcType=INTEGER} AS MID_PRODUCE_ORDER, #{item.midSysAnalysis,jdbcType=VARCHAR} AS MID_SYS_ANALYSIS, #{item.midHandAnalysis,jdbcType=VARCHAR} AS MID_HAND_ANALYSIS, #{item.midSysAnalysis,jdbcType=VARCHAR} AS MID_REMARK, #{item.cxClass3Plan,jdbcType=INTEGER} AS CX_CLASS3_PLAN, #{item.cxClass4Plan,jdbcType=INTEGER} AS CX_CLASS4_PLAN, #{item.cxClass5Plan,jdbcType=INTEGER} AS CX_CLASS5_PLAN, #{item.cxClass6Plan,jdbcType=INTEGER} AS CX_CLASS6_PLAN, #{item.cxClass7Plan,jdbcType=INTEGER} AS CX_CLASS7_PLAN, #{item.cxClass8Plan,jdbcType=INTEGER} AS CX_CLASS8_PLAN, #{item.remark,jdbcType=VARCHAR} AS REMARK, #{item.dataVersion,jdbcType=VARCHAR} AS DATA_VERSION, #{item.companyCode,jdbcType=VARCHAR} AS COMPANY_CODE, #{item.factoryCode,jdbcType=VARCHAR} AS FACTORY_CODE
) AS t WHERE NOT EXISTS ( SELECT 1 FROM MES_TQ_SCHEDULE_RESULT WHERE SCHEDULE_DATE = t.SCHEDULE_DATE AND MACHINE_CODE = t.MACHINE_CODE AND BEAD_CODE = t.BEAD_CODE )

mapper.delete:
DELETE FROM MES_TQ_SCHEDULE_RESULT
WHERE SCHEDULE_DATE = #{scheduleDate}
AND DATA_VERSION = #{dataVersion}

mapper.select:
SELECT SCHEDULE_DATE, MACHINE_CODE, BEAD_CODE
FROM MES_TQ_SCHEDULE_RESULT
WHERE

    (SCHEDULE_DATE = #{item.scheduleDate}
     AND MACHINE_CODE = #{item.machineCode}
     AND BEAD_CODE = #{item.beadCode})

mapper.delete:
DELETE FROM MES_TQ_SCHEDULE_RESULT WHERE

    (SCHEDULE_DATE = #{item.scheduleDate}
     AND MACHINE_CODE = #{item.machineCode}
     AND BEAD_CODE = #{item.beadCode})
